#!/usr/bin/env python3
"""يولّد components/quran/tajweed3Data.ts: «التجويد الشامل» بثلاث لغات (فصحى / مصري / خليجي).
المادة العلمية مأخوذة من «التمهيد في علم التجويد» لابن الجزري (public/library/tamhid)، والأمثلة مواضع حقيقية يتحقق منها هذا السكربت آليًا."""
import json, re

q = json.load(open('public/quran/hafs.json', encoding='utf-8'))


def norm(s):
    s = re.sub('[ؐ-ًؚ-ٰٟۖ-ۭـ]', '', s)
    s = re.sub('[أإآٱ]', 'ا', s).replace('ى', 'ي').replace('ة', 'ه').replace('\xa0', '').replace('۞', '').replace('۩', '')
    return s.replace('ء', '').replace('ئ', 'ي').replace('ؤ', 'و')


NW = [[norm(w) for w in a[4].split(' ')] for a in q['ayas']]


def find_any(phrase, start=0):
    p = [norm(w) for w in phrase.split()]
    for i, nw in enumerate(NW):
        for k in range(len(nw) - len(p) + 1):
            if nw[k:k + len(p)] == p:
                return {'s': q['ayas'][i][0], 'a': q['ayas'][i][1], 'f': k, 't': k + len(p)}
    raise SystemExit('not found: ' + phrase)


def E(phrase, note=''):
    r = find_any(phrase)
    r['n'] = note
    return r


def S(id, icon, title, intro, items):
    return {'id': id, 'icon': icon, 'title': title, 'intro': intro, 'items': items}


def I(name, f, e, g, ex=None):
    return {'name': name, 'f': f, 'e': e, 'g': g, 'ex': ex or []}


