js = json.dumps(OUT, ensure_ascii=False, separators=(',', ':'))
hdr = """/* التجويد الشامل بثلاث لغات — مولَّد آليًا بالأداة tools/build_tajweed3.py. الأمثلة مواضع حقيقية من نص المصحف. */
export type Tj3Ex = { s: number; a: number; f: number; t: number; n: string };
export type Tj3Item = { name: string; f: string; e: string; g: string; ex: Tj3Ex[] };
export type Tj3Sec = { id: string; title: string; icon: string; intro: { f: string; e: string; g: string }; items: Tj3Item[] };
"""
open('components/quran/tajweed3Data.ts', 'w', encoding='utf-8').write(hdr + 'export const TAJWEED3: Tj3Sec[] = ' + js + ';\n')
